-- ====================================================
-- SUPABASE / POSTGRESQL SCHEMA AND DATA EXPORT
-- Generated from local SQLite database
-- ====================================================

-- 1. Employees Table
CREATE TABLE IF NOT EXISTS public.employees (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    matricule TEXT,
    nom_prenom TEXT NOT NULL,
    role TEXT DEFAULT 'user',
    password TEXT,
    d_rec TEXT,
    d_f_contrat TEXT,
    personnel TEXT,
    fonction TEXT,
    observation TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    t_combinaison TEXT,
    t_blouson TEXT,
    t_pantalon TEXT,
    t_parka TEXT,
    t_pantalon_ord TEXT,
    t_chemise_ord TEXT,
    t_tshirt_ord TEXT,
    t_pull TEXT,
    p_chaussure TEXT,
    t_veste_cuire TEXT,
    service TEXT
);

-- 2. Wells Table
CREATE TABLE IF NOT EXISTS public.wells (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    purpose TEXT DEFAULT 'Oil Producer',
    completion_type TEXT DEFAULT 'COMPLETION SIMPLE',
    reservoir TEXT,
    field TEXT,
    elevation_sol DOUBLE PRECISION DEFAULT 0,
    elevation_forage DOUBLE PRECISION DEFAULT 0,
    elevation_production DOUBLE PRECISION DEFAULT 0,
    spool_prod TEXT,
    packer_type TEXT,
    susp_tbg TEXT,
    etan_tbg TEXT,
    origine_cotes TEXT,
    xmas_tree_brand TEXT,
    xmas_tree_type TEXT,
    xmas_tree_ract_sup TEXT,
    xmas_tree_pressure TEXT,
    xmas_tree_attache_tbg TEXT,
    xmas_tree_embase TEXT,
    xmas_tree_reduction TEXT,
    xmas_tree_olive TEXT,
    vannes_sas_marque TEXT,
    vannes_sas_nombre TEXT,
    vannes_sas_serie TEXT,
    vannes_maitresse_marque TEXT,
    vannes_maitresse_nombre TEXT,
    vannes_maitresse_serie TEXT,
    vannes_lat_tbg_marque TEXT,
    vannes_lat_tbg_nombre TEXT,
    vannes_lat_tbg_serie TEXT,
    vannes_lat_csg_marque TEXT,
    vannes_lat_csg_nombre TEXT,
    vannes_lat_csg_serie TEXT,
    observations TEXT,
    folio TEXT,
    folio_to_cancel TEXT,
    prod_tbg_od TEXT,
    prod_tbg_grade TEXT,
    prod_tbg_weight TEXT,
    updated_date TEXT,
    end_operation_date TEXT,
    vu_by TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 3. Casing Strings Table
CREATE TABLE IF NOT EXISTS public.casing_strings (
    id TEXT PRIMARY KEY,
    well_id TEXT NOT NULL REFERENCES public.wells(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    borehole_size TEXT NOT NULL,
    casing_size TEXT NOT NULL,
    top_depth DOUBLE PRECISION NOT NULL DEFAULT 0,
    shoe_depth DOUBLE PRECISION NOT NULL,
    drilled_depth DOUBLE PRECISION NOT NULL,
    top_of_cement DOUBLE PRECISION,
    top_of_liner DOUBLE PRECISION,
    top_of_fonde DOUBLE PRECISION,
    grade TEXT,
    weight DOUBLE PRECISION,
    connection TEXT,
    observations TEXT,
    display_order INTEGER DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 4. Tubing Components Table
CREATE TABLE IF NOT EXISTS public.tubing_components (
    id TEXT PRIMARY KEY,
    well_id TEXT NOT NULL REFERENCES public.wells(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    type TEXT NOT NULL DEFAULT 'Tubing',
    od TEXT NOT NULL,
    length DOUBLE PRECISION NOT NULL,
    bottom_depth DOUBLE PRECISION NOT NULL,
    is_cote_product_added BOOLEAN DEFAULT FALSE,
    observations TEXT,
    qty TEXT,
    custom_type TEXT,
    min_id TEXT,
    display_order INTEGER DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 5. Perforation Zones Table
CREATE TABLE IF NOT EXISTS public.perforation_zones (
    id TEXT PRIMARY KEY,
    well_id TEXT NOT NULL REFERENCES public.wells(id) ON DELETE CASCADE,
    top_depth DOUBLE PRECISION NOT NULL,
    bottom_depth DOUBLE PRECISION NOT NULL,
    height DOUBLE PRECISION,
    perfo_type TEXT,
    diameter TEXT,
    density DOUBLE PRECISION,
    shots DOUBLE PRECISION,
    observations TEXT,
    calage TEXT,
    display_order INTEGER DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 6. Custom Tool Types Table
CREATE TABLE IF NOT EXISTS public.custom_tool_types (
    id TEXT PRIMARY KEY,
    type TEXT NOT NULL UNIQUE,
    default_name TEXT NOT NULL,
    default_od TEXT DEFAULT '2''7/8',
    default_custom_type TEXT DEFAULT 'EU',
    default_min_id TEXT DEFAULT '',
    french_designation TEXT NOT NULL,
    display_order INTEGER DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 7. Well History Table
CREATE TABLE IF NOT EXISTS public.well_history (
    id TEXT PRIMARY KEY,
    well_id TEXT NOT NULL REFERENCES public.wells(id) ON DELETE CASCADE,
    folio TEXT NOT NULL,
    snapshot TEXT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    edited_by TEXT,
    CONSTRAINT unique_well_folio UNIQUE(well_id, folio)
);

-- 8. Sync Meta Table
CREATE TABLE IF NOT EXISTS public.sync_meta (
    key TEXT PRIMARY KEY,
    value TEXT
);

-- Enable Row Level Security (RLS) & Policies
ALTER TABLE public.employees ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.wells ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.casing_strings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.tubing_components ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.perforation_zones ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.custom_tool_types ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.well_history ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.sync_meta ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Allow public read/write access" ON public.employees;
DROP POLICY IF EXISTS "Allow public read/write access" ON public.wells;
DROP POLICY IF EXISTS "Allow public read/write access" ON public.casing_strings;
DROP POLICY IF EXISTS "Allow public read/write access" ON public.tubing_components;
DROP POLICY IF EXISTS "Allow public read/write access" ON public.perforation_zones;
DROP POLICY IF EXISTS "Allow public read/write access" ON public.custom_tool_types;
DROP POLICY IF EXISTS "Allow public read/write access" ON public.well_history;
DROP POLICY IF EXISTS "Allow public read/write access" ON public.sync_meta;

CREATE POLICY "Allow public read/write access" ON public.employees FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow public read/write access" ON public.wells FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow public read/write access" ON public.casing_strings FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow public read/write access" ON public.tubing_components FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow public read/write access" ON public.perforation_zones FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow public read/write access" ON public.custom_tool_types FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow public read/write access" ON public.well_history FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Allow public read/write access" ON public.sync_meta FOR ALL USING (true) WITH CHECK (true);

